        const normalLine='rockN = normalize(max(abs(grainDet),.000001)*terrainN - grainGradient);';
        if(!shader.fragmentShader.includes(normalLine))throw Error('index1-5 coastal normal anchor');
        shader.fragmentShader=shader.fragmentShader.replace(normalLine,'rockN = normalize(max(abs(grainDet),.000001)*terrainN - grainGradient*.12);');
        const finalNormal='normal = normalize(mat3(viewMatrix) * wd);';
        if(!shader.fragmentShader.includes(finalNormal))throw Error('index1-5 coastal roughness anchor');
        shader.fragmentShader=shader.fragmentShader.replace(finalNormal,finalNormal+'\n      vec3 aaDx=dFdx(normal),aaDy=dFdy(normal);\n      float coastalVariance=min(.24,dot(aaDx,aaDx)+dot(aaDy,aaDy));\n      roughnessFactor=clamp(roughnessFactor+coastalVariance,.62,.99);');
